// ── Helpers ──────────────────────────────────────────────────────────
const emptyAlbum = () => ({ numarCopii: 1, numeCopil: "", titlu: "", size: null });
const emptyMozaic = () => ({ numarCopii: 1, numeCopil: "", size: null, frame: "alb" });
const emptyArticol = () => ({
  tip: "tricou", culoare: "#FAFAFA", numeCuloare: "Alb", marime: "M",
  tipPersonalizare: "lucrare", numarCopii: 1,
});

function sum(items, fn) { return items.reduce((a, i) => a + (fn(i) || 0), 0); }

// ── Reduceri ─────────────────────────────────────────────────────────
// Album:   40% reducere pe fiecare copie suplimentară a aceluiași album
// Mozaic:  40% reducere pe fiecare copie suplimentară (dim. egală sau mai mică)
//          20% reducere dacă se comandă alături de un album
// Amintiri: 30% reducere pe copii suplimentare (același design)
//           20% reducere dacă se comandă alături de album sau mozaic

function albumPrice(a) {
  if (!a.size) return 0;
  const base = ALBUM_SIZES.find(s => s.label === a.size)?.price || 0;
  const copies = a.numarCopii || 1;
  // Prima copie: preț întreg; restul: -40%
  return base + (copies - 1) * Math.round(base * 0.60);
}

function mozaicPrice(m, hasAlbum = false) {
  if (!m.size) return 0;
  const base = MOSAIC_SIZES.find(s => s.label === m.size)?.price || 0;
  const copies = m.numarCopii || 1;
  // Prima copie: preț întreg (sau -20% dacă există album); restul: -40%
  const firstPrice = hasAlbum ? Math.round(base * 0.80) : base;
  return firstPrice + (copies - 1) * Math.round(base * 0.60);
}

function articolPrice(a, hasAlbumOrMozaic = false) {
  // Tote bag: 120 lei (lucrare), 185 lei (colaj)
  // Tricou:   150 lei (lucrare), 215 lei (colaj)
  const isTricou = a.tip === "tricou";
  const isColaj  = a.tipPersonalizare === "colaj";
  let base = isTricou
    ? (isColaj ? 215 : 150)
    : (isColaj ? 185 : 120);
  const copies = a.numarCopii || 1;
  // 20% reducere dacă există album/mozaic în comandă
  const discountedBase = hasAlbumOrMozaic ? Math.round(base * 0.80) : base;
  // Prima copie: preț (eventual redus); restul: -30% din prețul de bază original
  return discountedBase + (copies - 1) * Math.round(base * 0.70);
}

// ── Step progress bar ────────────────────────────────────────────────
const STEPS = ["Album","Mozaic","Amintiri 2 Go","Galerie Digitală","Finalizare"];
function StepBar({ current }) {
  return (
    <div style={{ display:"flex", alignItems:"center", gap:0, padding:"0 24px", marginBottom:28 }}>
      {STEPS.map((s, i) => {
        const done = i < current;
        const active = i === current;
        const color = active || done ? C.navy : C.gray400;
        return (
          <div key={s} style={{ display:"flex", alignItems:"center", flex: i < STEPS.length-1 ? 1 : 0 }}>
            <div style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:4, minWidth:60 }}>
              <div style={{
                width:28, height:28, borderRadius:"50%",
                background: done ? C.navy : active ? C.navy : C.gray200,
                border: `2px solid ${done ? C.navy : active ? C.navy : C.gray200}`,
                display:"flex", alignItems:"center", justifyContent:"center",
                color: done || active ? C.white : C.gray400,
                fontSize:12, fontWeight:700, transition:"all .3s",
              }}>
                {done ? "✓" : i+1}
              </div>
              <span style={{ fontSize:10, fontWeight: active ? 700 : 400, color, whiteSpace:"nowrap" }}>{s}</span>
            </div>
            {i < STEPS.length-1 && (
              <div style={{ flex:1, height:2, background: done ? C.navy : C.gray200, margin:"0 4px", marginBottom:18, transition:"background .3s" }} />
            )}
          </div>
        );
      })}
    </div>
  );
}

// ── Quantity control ─────────────────────────────────────────────────
function QtyControl({ value, onChange, min=0, accent=C.salmon }) {
  return (
    <div style={{ display:"flex", alignItems:"center", gap:12 }}>
      <button onClick={() => onChange(Math.max(min, value-1))} style={{
        width:32, height:32, borderRadius:"50%", border:`2px solid ${accent}`,
        background:"transparent", color:accent, fontSize:18, fontWeight:700,
        cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center",
      }}>−</button>
      <span style={{ fontWeight:700, fontSize:16, minWidth:20, textAlign:"center", color:C.gray800 }}>{value}</span>
      <button onClick={() => onChange(value+1)} style={{
        width:32, height:32, borderRadius:"50%", background:accent,
        border:"none", color:C.white, fontSize:18, fontWeight:700,
        cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center",
      }}>+</button>
    </div>
  );
}

// ── Section header ───────────────────────────────────────────────────
function SectionHeader({ label, accent }) {
  return (
    <div style={{
      background:accent, borderRadius:8, padding:"8px 16px",
      color:C.white, fontWeight:700, fontSize:13, letterSpacing:1,
      marginBottom:12, marginTop:16,
    }}>{label}</div>
  );
}

// ── Total bar ────────────────────────────────────────────────────────
function TotalBar({ label, amount, accent=C.navy }) {
  return (
    <div style={{
      background:accent, borderRadius:12, padding:"16px 24px",
      color:C.white, textAlign:"center", marginTop:20,
    }}>
      <div style={{ fontSize:11, fontWeight:600, letterSpacing:1.5, opacity:.8, marginBottom:4 }}>{label}</div>
      <div style={{ fontSize:28, fontWeight:800 }}>{amount} LEI</div>
      {amount > 0 && <div style={{ fontSize:11, opacity:.7, marginTop:2 }}>Reduceri incluse</div>}
    </div>
  );
}

// ── Primary button ───────────────────────────────────────────────────
function Btn({ children, onClick, accent=C.salmon, disabled=false, outline=false }) {
  return (
    <button onClick={onClick} disabled={disabled} style={{
      width:"100%", padding:"14px", borderRadius:10, fontSize:15, fontWeight:700,
      background: outline ? "transparent" : disabled ? C.gray200 : accent,
      color: outline ? accent : disabled ? C.gray400 : C.white,
      border: outline ? `2px solid ${accent}` : "none",
      cursor: disabled ? "not-allowed" : "pointer",
      marginTop:12, letterSpacing:.5, transition:"opacity .2s",
    }}>{children}</button>
  );
}

