// ════════════════════════════════════════════════════════════════════
// MAIN APP
// ════════════════════════════════════════════════════════════════════
const STEP_ACCENTS = [C.albumPurple, C.mosaicGold, C.amintiriBlue, C.galeriePink, C.salmon];

export default function App() {
  const [page, setPage] = useState("home"); // "home" | "config"
  const [step, setStep] = useState(0);
  const [submitted, setSubmitted] = useState(false);
  const [data, setData] = useState({
    mozaice: [],
    albume: [],
    articole: [],
    galerie: "gratuit",
    galerieNrLucrari: 26,
    notesMozaic: "",
    notesAlbum: "",
    notesAmintiri: "",
    contact: { nume:"", telefon:"", email:"", newsletter:"", metodaContact:"", lucrariOriginale:"" },
  });

  const accent = STEP_ACCENTS[step] || C.salmon;
  const grandTotal = calcGrandTotal(data);

  async function handleSubmit() {
    const grandTotal = calcGrandTotal(data);
    const hasAlbum   = data.albume.some(a => a.size);
    const hasMozaic  = data.mozaice.some(m => m.size);
    const hasAlbOrMoz = hasAlbum || hasMozaic;

    // Build order summary text
    const albumLines = data.albume
      .filter(a => a.size)
      .map((a,i) => `Album ${i+1}: ${a.size} | Copil: ${a.numeCopil||"-"} | Titlu: ${a.titlu||"-"} | Copii: ${a.numarCopii} | Pret: ${albumPrice(a)} LEI`)
      .join("\n");

    const mozaicLines = data.mozaice
      .filter(m => m.size)
      .map((m,i) => `Mozaic ${i+1}: ${m.size} | Copil: ${m.numeCopil||"-"} | Rama: ${m.frame} | Copii: ${m.numarCopii} | Pret: ${mozaicPrice(m, hasAlbum)} LEI`)
      .join("\n");

    const amintiriLines = data.articole
      .map((a,i) => `Articol ${i+1}: ${a.tip} | ${a.tipPersonalizare} | Marime: ${a.marime||"-"} | Culoare: ${a.numeCuloare||a.culoare} | Copii: ${a.numarCopii} | Pret: ${articolPrice(a, hasAlbOrMoz)} LEI`)
      .join("\n");

    const galerieText = data.galerie === "abonament"
      ? `Abonament lunar - ${data.galerieNrLucrari} lucrari - ${galleryPriceForCount(data.galerieNrLucrari)} LEI/luna`
      : "1 luna gratuit";

    const metodaContact = Array.isArray(data.contact.metodaContact)
      ? data.contact.metodaContact.join(", ")
      : data.contact.metodaContact;

    const payload = {
      "Nume": data.contact.nume,
      "Telefon": data.contact.telefon,
      "Email": data.contact.email,
      "Metoda contact": metodaContact,
      "Newsletter": data.contact.newsletter,
      "Lucrari originale": data.contact.lucrariOriginale === "inapoi" ? "Le vrea inapoi" : "Nu le mai vrea",
      "ALBUM": albumLines || "Niciun album",
      "Note album": data.notesAlbum || "-",
      "MOZAIC": mozaicLines || "Niciun mozaic",
      "Note mozaic": data.notesMozaic || "-",
      "AMINTIRI 2 GO": amintiriLines || "Niciun articol",
      "Note amintiri": data.notesAmintiri || "-",
      "GALERIE DIGITALA": galerieText,
      "TOTAL COMANDA": `${grandTotal} LEI`,
    };

    try {
      const res = await fetch("https://formspree.io/f/xnjwqvbk", {
        method: "POST",
        headers: { "Content-Type": "application/json", "Accept": "application/json" },
        body: JSON.stringify(payload),
      });
      if (res.ok) {
        setSubmitted(true);
      } else {
        alert("A apărut o eroare. Te rugăm să încerci din nou sau să ne contactezi direct.");
      }
    } catch(e) {
      alert("A apărut o eroare de rețea. Te rugăm să încerci din nou.");
    }
  }

  if (page === "home") {
    return <HomePage onStart={() => setPage("config")} />;
  }

  return (
    <div style={{
      minHeight:"100vh", background:C.cream,
      fontFamily:"'Nunito', 'Segoe UI', sans-serif",
    }}>
      {/* Top bar */}
      <div style={{
        background:C.white, borderBottom:`2px solid ${accent}`,
        padding:"12px 24px", display:"flex", justifyContent:"space-between", alignItems:"center",
        position:"sticky", top:0, zIndex:100, transition:"border-color .3s",
      }}>
        <button onClick={() => { setPage("home"); setStep(0); }} style={{
          background:"none", border:"none", cursor:"pointer", padding:0,
        }}>
          <img src={IMG_LOGO} alt="ARTHIVA" style={{ height:36, objectFit:"contain" }} />
        </button>
        <span style={{ fontWeight:700, fontSize:13, color:accent }}>{STEPS[step]}</span>
      </div>

      <div style={{ maxWidth:540, margin:"0 auto", padding:"24px 16px 80px" }}>
        {/* Step indicator */}
        <div style={{ marginBottom:4, color:C.gray400, fontSize:12, fontWeight:600 }}>
          Pas {step+1} din {STEPS.length}
        </div>
        <StepBar current={step} />

        {/* Back button */}
        {step > 0 && (
          <button onClick={() => setStep(s=>s-1)} style={{
            background:"none", border:"none", color:C.gray400, fontWeight:600,
            fontSize:13, cursor:"pointer", marginBottom:16, padding:0,
          }}>← Înapoi</button>
        )}

        {/* Step content */}
        <div style={{
          background:C.white, borderRadius:16, padding:20,
          boxShadow:"0 4px 24px rgba(0,0,0,.07)",
        }}>
          {step===0 && <StepAlbum data={data} onChange={setData} />}
          {step===1 && <StepMozaic data={data} onChange={setData} />}
          {step===2 && <StepAmintiri data={data} onChange={setData} />}
          {step===3 && <StepGalerie data={data} onChange={setData} />}
          {step===4 && <StepFinalizare data={data} onChange={setData} onSubmit={handleSubmit} submitted={submitted} />}
        </div>

        {/* Continue / floating total */}
        {step < 4 && (
          <div style={{ marginTop:16 }}>
            {grandTotal > 0 && (
              <div style={{ textAlign:"center", marginBottom:8 }}>
                <span style={{ fontSize:12, color:C.gray400, fontWeight:600 }}>
                  Total curent: <strong style={{ color:C.navy }}>{grandTotal} LEI</strong>
                </span>
              </div>
            )}
            <Btn onClick={() => setStep(s=>s+1)} accent={C.navy}>
              Continuă →
            </Btn>
          </div>
        )}
      </div>
    </div>
  );
}
